390   *
   391   * The current char value, if using UTF-8 this may actually span multiple
   392   * bytes in the input buffer. Implement the end of line normalization:
   393   * 2.11 End-of-Line Handling
   394   * If the encoding is unspecified, in the case we find an ISO-Latin-1
   395   * char, then the encoding converter is plugged in automatically.
   396   *
   397   * Returns the current char value and its length
   398   */
   399
   400  static int
   401  htmlCurrentChar(xmlParserCtxtPtr ctxt, int *len) {
   402      const unsigned char *cur;
   403      unsigned char c;
   404      unsigned int val;
   405
   406      if (ctxt->instate == XML_PARSER_EOF)
   407          return(0);
   408
   409      if (ctxt->token != 0) {
   410          *len = 0;
   411          return(ctxt->token);
   412      }
   413
   414      if ((ctxt->input->end - ctxt->input->cur < INPUT_CHUNK) &&
   415          (xmlParserGrow(ctxt) < 0))
   416          return(0);
   417
   418      if (ctxt->charset != XML_CHAR_ENCODING_UTF8) {
   419          xmlChar * guess;
   420          xmlCharEncodingHandlerPtr handler;
   421
   422          /*
   423           * Assume it's a fixed length encoding (1) with
   424           * a compatible encoding for the ASCII set, since
   425           * HTML constructs only use < 128 chars
   426           */
   427          if (*ctxt->input->cur < 0x80) {
   428              *len = 1;
   429              if ((*ctxt->input->cur == 0) &&
   430                  (ctxt->input->cur < ctxt->input->end)) {
   431                  htmlParseErrInt(ctxt, XML_ERR_INVALID_CHAR,
   432                                  "Char 0x%X out of allowed range\n", 0);
   433                  return(' ');
   434              }
   435              return(*ctxt->input->cur);
   436          }
   437
   438          /*
   439           * Humm this is bad, do an automatic flow conversion
   440           */
   441          guess = htmlFindEncoding(ctxt);
   442          if (guess == NULL) {
   443              xmlSwitchEncoding(ctxt, XML_CHAR_ENCODING_8859_1);
   444          } else {
   445              if (ctxt->input->encoding != NULL)
   446                  xmlFree((xmlChar *) ctxt->input->encoding);
   447              ctxt->input->encoding = guess;
   448              handler = xmlFindCharEncodingHandler((const char *) guess);
   449              if (handler != NULL) {
   450                  /*
   451                   * Don't use UTF-8 encoder which isn't required and
   452                   * can produce invalid UTF-8.
   453                   */
   454                  if (!xmlStrEqual(BAD_CAST handler->name, BAD_CAST "UTF-8"))
   455                      xmlSwitchToEncoding(ctxt, handler);
   565          c = *cur;
   566          if (c & 0x80) {
   567              size_t avail;
   568
   569              if (c == 0xC0)
   570                  goto encoding_error;
   571
   572              avail = ctxt->input->end - ctxt->input->cur;
   573
   574              if ((avail < 2) || (cur[1] & 0xc0) != 0x80)
   575                  goto encoding_error;
   576              if ((c & 0xe0) == 0xe0) {
   577                  unsigned int val;
   578
   579                  if ((avail < 3) || (cur[2] & 0xc0) != 0x80)
   580                      goto encoding_error;
   581                  if ((c & 0xf0) == 0xf0) {
   582                      if (((c & 0xf8) != 0xf0) ||
   583                          (avail < 4) || ((cur[3] & 0xc0) != 0x80))
   584                          goto encoding_error;
   585                      /* 4-byte code */
   586                      ctxt->input->cur += 4;
   587                      val = (cur[0] & 0x7) << 18;
   588                      val |= (cur[1] & 0x3f) << 12;
   589                      val |= (cur[2] & 0x3f) << 6;
   590                      val |= cur[3] & 0x3f;
   591                  } else {
   592                      /* 3-byte code */
   593                      ctxt->input->cur += 3;
   594                      val = (cur[0] & 0xf) << 12;
   595                      val |= (cur[1] & 0x3f) << 6;
   596                      val |= cur[2] & 0x3f;
   597                  }
   598                  if (((val > 0xd7ff) && (val < 0xe000)) ||
   599                      ((val > 0xfffd) && (val < 0x10000)) ||
   600                      (val >= 0x110000)) {
   601                  xmlErrEncodingInt(ctxt, XML_ERR_INVALID_CHAR,
   602                                    "Char 0x%X out of allowed range\n",
   603                                    val);
   604                  }
   605              } else
   606                  /* 2-byte code */
   607                  ctxt->input->cur += 2;
   608          } else
   609              /* 1-byte code */
   610              ctxt->input->cur++;
   611      } else {
   612          /*
   613           * Assume it's a fixed length encoding (1) with
   614           * a compatible encoding for the ASCII set, since
   615           * XML constructs only use < 128 chars
   616           */
   617
   618          if (*(ctxt->input->cur) == '\n') {
   619              ctxt->input->line++; ctxt->input->col = 1;
   620          } else
   621              ctxt->input->col++;
   622          ctxt->input->cur++;
   623      }
   624      return;
   625  encoding_error:
   626      /*
   627       * If we detect an UTF8 error that probably mean that the
   628       * input encoding didn't get properly advertised in the
   629       * declaration header. Report the error and switch the encoding
   630       * to ISO-Latin-1 (if you don't like this policy, just declare the
   631       * encoding !)
   632       */
   633      if ((ctxt == NULL) || (ctxt->input == NULL) ||
   634          (ctxt->input->end - ctxt->input->cur < 4)) {
   635          __xmlErrEncoding(ctxt, XML_ERR_INVALID_CHAR,
   636                       "Input is not proper UTF-8, indicate encoding !\n",
   637                       NULL, NULL);
   638      } else {
   639          char buffer[150];
   640
   641          snprintf(buffer, 149, "Bytes: 0x%02X 0x%02X 0x%02X 0x%02X\n",
   642                          ctxt->input->cur[0], ctxt->input->cur[1],
   643                          ctxt->input->cur[2], ctxt->input->cur[3]);
   644          __xmlErrEncoding(ctxt, XML_ERR_INVALID_CHAR,
   645                       "Input is not proper UTF-8, indicate encoding !\n%s",
   646                       BAD_CAST buffer, NULL);
   647      }
   648      ctxt->charset = XML_CHAR_ENCODING_8859_1;
   649      ctxt->input->cur++;
   650      return;
